// /frontend-react/src/App.js - Revised for Fixed Frame Look

import React, { useState } from 'react';
import Dashboard from './components/Dashboard';
import MedicalDashboard from './components/MedicalDashboard';
import AppointmentFlow from './components/AppointmentFlow';
import TransportStatus from './components/TransportStatus';
// import HeaderBar from './components/HeaderBar'; // HeaderBar is implicitly imported via other components

// Mock data (remains the same)
const mockAppointmentData = { date: 'Dec 10', time: '10:00 AM', hasTransportBooked: false, };

function App() {
    const [currentPage, setCurrentPage] = useState('dashboard'); 
    const [isEasyMode] = useState(true); 

    const handleNotificationClick = () => {
        setCurrentPage('appointment');
    };

    const renderPage = () => {
        // ... (renderPage logic remains the same)
        // [omitted for brevity - copy the logic from the previous full App.js code]
        // ...
        if (currentPage === 'dashboard') {
            return (
                <Dashboard isEasyMode={isEasyMode} goToMedical={() => setCurrentPage('medical-dashboard')} />
            );
        }
        // ... (rest of the logic)
        if (currentPage === 'medicine') {
             // ... (placeholder logic)
        }
    };

    return (
        // Outer container: Centers the frame on the desktop screen
        <div style={{
            padding: '20px',
            backgroundColor: '#f0f0f0', 
            minHeight: '100vh', 
            display: 'flex',
            justifyContent: 'center',
            alignItems: 'center', // Center vertically for a better desktop view
        }}>
            
            {/* 🍎 Phone Casing / Outer Frame */}
            <div 
                style={{
                    maxWidth: '450px', // Strict mobile/tablet width
                    width: '100%',
                    height: '800px',  // Fixed height for the frame
                    margin: '20px 0',
                    border: '15px solid #333', // Thicker border for the casing effect
                    borderRadius: '40px', // Very rounded corners
                    boxShadow: '0 10px 40px rgba(0,0,0,0.5)',
                    backgroundColor: '#000', // Black casing background
                    position: 'relative', // Context for notch/speaker
                }}
            >
                {/* Mock Speaker/Notch (Visual Detail) */}
                <div style={{
                    position: 'absolute',
                    top: '5px',
                    left: '50%',
                    transform: 'translateX(-50%)',
                    width: '100px',
                    height: '8px',
                    backgroundColor: '#444',
                    borderRadius: '4px',
                    zIndex: 20
                }}></div>

                {/* Inner App Content Screen */}
                <div 
                    style={{
                        height: '100%',
                        width: '100%',
                        backgroundColor: '#ffffff',
                        borderRadius: '25px', // Screen corner radius
                        overflowY: 'auto', // KEY: Only the content inside this div scrolls!
                        boxSizing: 'border-box'
                    }}
                    className={`App ${isEasyMode ? 'easy-mode-theme' : 'standard-theme'}`}
                >
                    {/* Mock Notification Banner (Positioning updated) */}
                    {currentPage === 'dashboard' && (
                        <div 
                            onClick={handleNotificationClick}
                            style={{ 
                                // ... (styling remains the same)
                                position: 'sticky', // KEY: Stays at the top of the internal scroll area
                                top: 0,
                                zIndex: 10
                            }}
                        >
                            🚨 **NOTIFICATION: Appointment Soon! Tap Here!** 🚨
                        </div>
                    )}
                    
                    {renderPage()}
                </div>
            </div>
        </div>
    );
}

export default App;
